public class PagoServicioTest {

  @Test
  void spyEjecutaCodigoRealPeroIntercepta() {
    PagoServicio real = new PagoServicio();
    PagoServicio spy = Mockito.spy(real);

    doReturn("resultado-mock").when(spy).buscar(anyLong());

    assertEquals("resultado-mock", spy.buscar(1L));
    // El metodo real NO se ejecuto para buscar()

    // Otros metodos si ejecutan el codigo real
    spy.registrar(new Pago(100.0));
    verify(real).registrar(any(Pago.class));
  }

  @Test
  void doReturnEvitaEjecutarMetodoReal() {
    MiServicio real = new MiServicio();
    MiServicio spy = spy(real);

    // when().thenReturn() ejecutaria el metodo real primero
    // doReturn() lo evita completamente
    doReturn(Collections.emptyList()).when(spy).buscarTodos();

    List<MiObjeto> resultado = spy.buscarTodos();
    assertTrue(resultado.isEmpty());
  }
}

