@SpringBootTest(webEnvironment = WebEnvironment.RANDOM_PORT)
class CuentaApiIntegrationTest {

  @Autowired
  private TestRestTemplate restTemplate;

  @Test
  void obtenerCuentaExistente() {
    ResponseEntity<Cuenta> respuesta =
      restTemplate.getForEntity("/api/cuentas/1", Cuenta.class);

    assertEquals(HttpStatus.OK, respuesta.getStatusCode());
    assertNotNull(respuesta.getBody());
    assertEquals(1L, respuesta.getBody().getId());
  }

  @Test
  void crearCuenta() {
    Cuenta nueva = new Cuenta(null, "Test", 500.0);

    ResponseEntity<Cuenta> respuesta = restTemplate
      .postForEntity("/api/cuentas", nueva, Cuenta.class);

    assertEquals(HttpStatus.CREATED, respuesta.getStatusCode());
    assertNotNull(respuesta.getBody().getId());
  }

  @Test
  void eliminarCuenta() {
    restTemplate.delete("/api/cuentas/1");

    ResponseEntity<Cuenta> respuesta =
      restTemplate.getForEntity("/api/cuentas/1", Cuenta.class);

    assertEquals(HttpStatus.NOT_FOUND, respuesta.getStatusCode());
  }
}

